/** Score frozen baseline and causal-slot predictions against holdout diffs. */
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import type { AdaptiveCorrectionCandidate } from "./adaptive-stage-ranker.js";
import type { CausalCorrectionCandidate } from "./adaptive-stage-causal-ranker.js";
import { changedLineNumbers, declarationOwners } from "./evaluate-zod-owner-ranker.js";

interface Task { id: string; repo: string; number: number; url: string; title: string; body: string; fix_sha: string; pre_fix_sha: string }
interface Prediction { id: string; repo: string; input_hash: string; pre_fix_sha: string; fix_sha: string; adaptive: AdaptiveCorrectionCandidate[]; hybrid: CausalCorrectionCandidate[] }
const BENCHMARK = "adaptive-stage-causal-hybrid-transfer-v1";
const base = join(import.meta.dirname, "results", "2026-08-25-adaptive-stage-causal-hybrid-transfer-v1");
const adaptivePath = join(import.meta.dirname, "adaptive-stage-ranker.ts"); const causalPath = join(import.meta.dirname, "adaptive-stage-causal-ranker.ts");
const expectedAdaptiveHash = "40ceb9b4e0baf826793705dfd377fee2fe11f0c5401d9bd64085dba960be996f"; const expectedCausalHash = "3c9afa460042b109c6505c9368ef70fabce528a155e921898a475d1e7a55e42b";
const excludedSource = /(?:^|\/)(?:tests?|__tests__|test-data|fixtures?|examples?|benchmarks?|generated|docs?)(?:\/|$)|\.(?:test|spec)\.tsx?$|\.d\.ts$/i;
const hash = (value: string | Buffer): string => createHash("sha256").update(value).digest("hex");
const tasks = JSON.parse(readFileSync(`${base}.tasks.json`, "utf8")) as { adaptive_hash: string; causal_hash: string; task_hash: string; tasks: Task[] };
const frozen = JSON.parse(readFileSync(`${base}.predictions.json`, "utf8")) as { adaptive_hash: string; causal_hash: string; task_hash: string; prediction_hash: string; predictions: Prediction[] };
if (hash(readFileSync(adaptivePath)) !== expectedAdaptiveHash || tasks.adaptive_hash !== expectedAdaptiveHash || frozen.adaptive_hash !== expectedAdaptiveHash) throw new Error("adaptive hash mismatch");
if (hash(readFileSync(causalPath)) !== expectedCausalHash || tasks.causal_hash !== expectedCausalHash || frozen.causal_hash !== expectedCausalHash) throw new Error("causal hash mismatch");
if (hash(JSON.stringify(tasks.tasks)) !== tasks.task_hash || frozen.task_hash !== tasks.task_hash) throw new Error("task hash mismatch");
if (hash(JSON.stringify(frozen.predictions)) !== frozen.prediction_hash || frozen.predictions.length !== tasks.tasks.length) throw new Error("prediction hash mismatch");
for (let index = 0; index < tasks.tasks.length; index++) { const task = tasks.tasks[index]!, prediction = frozen.predictions[index]!; if (prediction.id !== task.id || prediction.pre_fix_sha !== task.pre_fix_sha || prediction.fix_sha !== task.fix_sha) throw new Error(`${task.id}: identity mismatch`); if (prediction.input_hash !== hash(JSON.stringify({ title: task.title, body: task.body }))) throw new Error(`${task.id}: input mismatch`); }
function sections(diff: string): Array<{ before: string; after: string; text: string }> { const matches = [...diff.matchAll(/^diff --git a\/(.+) b\/(.+)$/gm)]; return matches.map((match, index) => ({ before: match[1]!, after: match[2]!, text: diff.slice(match.index!, matches[index + 1]?.index ?? diff.length) })); }
const encoded = (path: string): string => path.split("/").map(encodeURIComponent).join("/");
async function raw(repo: string, sha: string, path: string): Promise<string | null> { const response = await fetch(`https://raw.githubusercontent.com/${repo}/${sha}/${encoded(path)}`); if (response.status === 404) return null; if (!response.ok) throw new Error(`${repo}:${path}: HTTP ${response.status}`); return response.text(); }
async function truth(task: Task): Promise<{ paths: string[]; symbols: string[] }> {
  const response = await fetch(`https://github.com/${task.repo}/pull/${task.number}.diff`); if (!response.ok) throw new Error(`${task.id}: diff HTTP ${response.status}`); const paths = new Set<string>(), symbols = new Set<string>();
  for (const section of sections(await response.text())) { const beforeMissing = /^--- \/dev\/null$/m.test(section.text), afterMissing = /^\+\+\+ \/dev\/null$/m.test(section.text), path = afterMissing ? section.before : section.after; if (!/\.tsx?$/.test(path) || excludedSource.test(path)) continue; paths.add(path); if (beforeMissing) continue; const before = await raw(task.repo, task.pre_fix_sha, section.before); if (!before) continue; const changed = changedLineNumbers(section.text).before; for (const span of declarationOwners(section.before, before)) if ([...changed].some((line) => line >= span.startLine && line <= span.endLine)) symbols.add(span.owner); }
  return { paths: [...paths].sort(), symbols: [...symbols].sort() };
}
const rows = [] as Array<{ id: string; repo: string; url: string; adaptive: AdaptiveCorrectionCandidate[]; hybrid: CausalCorrectionCandidate[]; ground_truth: { paths: string[]; symbols: string[] }; symbol_scorable: boolean; adaptive_hit: boolean; hybrid_hit: boolean; rescue: boolean; loss: boolean; adaptive_file: boolean; hybrid_file: boolean }>;
for (let index = 0; index < tasks.tasks.length; index++) {
  const task = tasks.tasks[index]!, prediction = frozen.predictions[index]!, ground = await truth(task); const adaptiveHit = prediction.adaptive.some((candidate) => ground.symbols.includes(candidate.owner)), hybridHit = prediction.hybrid.some((candidate) => ground.symbols.includes(candidate.owner)); const adaptivePath = prediction.adaptive[0]?.owner.split("::")[0], hybridPath = prediction.hybrid[0]?.owner.split("::")[0];
  rows.push({ id: task.id, repo: task.repo, url: task.url, adaptive: prediction.adaptive, hybrid: prediction.hybrid, ground_truth: ground, symbol_scorable: ground.symbols.length > 0, adaptive_hit: adaptiveHit, hybrid_hit: hybridHit, rescue: !adaptiveHit && hybridHit, loss: adaptiveHit && !hybridHit, adaptive_file: !!adaptivePath && ground.paths.includes(adaptivePath), hybrid_file: !!hybridPath && ground.paths.includes(hybridPath) });
  process.stderr.write(`[score ${index + 1}/${tasks.tasks.length}] ${task.id}: ${ground.symbols.length} pre-existing owner(s)\n`);
}
const scorable = rows.filter((row) => row.symbol_scorable), count = (key: "adaptive_hit" | "hybrid_hit" | "rescue" | "loss" | "adaptive_file" | "hybrid_file") => scorable.filter((row) => row[key]).length;
const repos = ["nestjs/nest", "honojs/hono"]; const rescuesByRepo = Object.fromEntries(repos.map((repo) => [repo, scorable.filter((row) => row.repo === repo && row.rescue).length]));
const rescues = count("rescue"), losses = count("loss"); const promoted = scorable.length >= 10 && rescues >= 2 && losses === 0 && repos.every((repo) => rescuesByRepo[repo]! >= 1);
const summary = { tasks: rows.length, scorable_tasks: scorable.length, adaptive_top5_hits: count("adaptive_hit"), hybrid_top5_hits: count("hybrid_hit"), rescues, losses, rescues_by_repository: rescuesByRepo, adaptive_file_hits: count("adaptive_file"), hybrid_file_hits: count("hybrid_file"), decision: promoted ? "promote-causal-slot" : "reject-causal-slot", exact_owner_policy: "disabled" };
const result = { benchmark: BENCHMARK, generated_at: new Date().toISOString(), adaptive_hash: expectedAdaptiveHash, causal_hash: expectedCausalHash, task_hash: tasks.task_hash, prediction_hash: frozen.prediction_hash, locked_rule: "At least 10 scorable, >=2 rescues, zero losses, and >=1 rescue in each repository.", summary, rows };
writeFileSync(`${base}.json`, `${JSON.stringify(result, null, 2)}\n`);
writeFileSync(`${base}.md`, ["# Adaptive causal-slot hybrid transfer v1", "", "Baseline and hybrid predictions were frozen from issue text and pre-fix source before any fix diff was requested.", "", "## Verdict", "", `**${summary.decision}**`, "", `- Scorable tasks: ${summary.scorable_tasks}/${summary.tasks}`, `- Adaptive top-five hits: ${summary.adaptive_top5_hits}/${summary.scorable_tasks}`, `- Hybrid top-five hits: ${summary.hybrid_top5_hits}/${summary.scorable_tasks}`, `- Rescues: ${summary.rescues}`, `- Losses: ${summary.losses}`, `- Rescues by repository: NestJS ${rescuesByRepo["nestjs/nest"]}; Hono ${rescuesByRepo["honojs/hono"]}`, `- Top-one file: adaptive ${summary.adaptive_file_hits}/${summary.scorable_tasks}; hybrid ${summary.hybrid_file_hits}/${summary.scorable_tasks}`, `- Exact-owner policy: ${summary.exact_owner_policy}`, "", "| task | repo | adaptive | causal slot | adaptive hit | hybrid hit | result | truth |", "|---|---|---|---|:---:|:---:|---|---|", ...rows.map((row) => `| [${row.id}](${row.url}) | ${row.repo} | ${row.adaptive.map((candidate) => `\`${candidate.owner}\``).join("<br>")} | ${row.hybrid[4] ? `\`${row.hybrid[4].owner}\`` : "none"} | ${row.adaptive_hit ? "yes" : "no"} | ${row.hybrid_hit ? "yes" : "no"} | ${row.rescue ? "rescue" : row.loss ? "loss" : "unchanged"} | ${row.ground_truth.symbols.map((owner) => `\`${owner}\``).join("<br>") || "unscorable"} |`), "", `Adaptive SHA-256: \`${expectedAdaptiveHash}\`.`, `Causal SHA-256: \`${expectedCausalHash}\`.`, `Task SHA-256: \`${tasks.task_hash}\`.`, `Prediction SHA-256: \`${frozen.prediction_hash}\`.`, "", "## Interpretation", "", promoted ? "The locked rule passed. The one-slot causal augmentation may replace adaptive rank five while ranks one through four stay unchanged; exact-owner output remains disabled." : "The locked rule failed. Do not productize or tune and rescore this causal hybrid on this holdout.", ""].join("\n"));
process.stdout.write(`${JSON.stringify(summary, null, 2)}\n`);
